describe('Image Scaling on Mobile Devices', () => {
  beforeEach(() => {
    cy.visit('/images');
  });

  it('should scale images down to fit screen width on mobile viewport', () => {
    // Set viewport to a mobile size
    cy.viewport('iphone-x');

    // Verify the image container is visible
    cy.get('[data-testid="image-container"]').should('be.visible');

    // Verify the image element exists
    cy.get('[data-testid="main-image"]').should('be.visible');

    // Verify the image has a max-width style applied
    cy.get('[data-testid="main-image"]').should('have.css', 'max-width', '100%');

    // Verify the image has a height style applied to maintain aspect ratio
    cy.get('[data-testid="main-image"]').should('have.css', 'height', 'auto');

    // Verify the image width is less than the viewport width
    cy.get('[data-testid="main-image"]').then(($img) => {
      const imgWidth = $img.width();
      const viewportWidth = cy.get('body').then(($body) => $body.width());
      expect(imgWidth).to.be.lessThan(viewportWidth);
    });

    // Verify the image is not overflowing the container
    cy.get('[data-testid="image-container"]').should('have.css', 'overflow', 'hidden');
  });

  it('should handle images with different aspect ratios and scale correctly', () => {
    // Navigate to a page with various images
    cy.visit('/images/gallery');

    // Set viewport to a tablet size
    cy.viewport('ipad-pro');

    // Verify the first image scales correctly
    cy.get('[data-testid="gallery-image-1"]').should('be.visible');
    cy.get('[data-testid="gallery-image-1"]').should('have.css', 'max-width', '100%');

    // Verify the second image (different aspect ratio) scales correctly
    cy.get('[data-testid="gallery-image-2"]').should('be.visible');
    cy.get('[data-testid="gallery-image-2"]').should('have.css', 'max-width', '100%');

    // Verify the third image (portrait) scales correctly
    cy.get('[data-testid="gallery-image-3"]').should('be.visible');
    cy.get('[data-testid="gallery-image-3"]').should('have.css', 'max-width', '100%');

    // Verify all images are within the viewport boundaries
    cy.get('[data-testid="gallery-image-1"]').should('not.have.css', 'overflow');
    cy.get('[data-testid="gallery-image-2"]').should('not.have.css', 'overflow');
    cy.get('[data-testid="gallery-image-3"]').should('not.have.css', 'overflow');

    // Verify image scaling is applied even when zoomed in on mobile
    cy.get('[data-testid="main-image"]').then(($img) => {
      const imgWidth = $img.width();
      const viewportWidth = cy.get('body').then(($body) => $body.width());
      expect(imgWidth).to.be.lessThanOrEqual(viewportWidth);
    });
  });
});
